      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence describes using RR and CI, but it does not describe methods for re-expressing synthesized results into another effect measure."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although RR is adopted for dichotomous data and mean difference was not feasible for time to recovery, the retrieved evidence does not provide an explicit justification for the choice of effect measure beyond these feasibility statements."
